import { useState } from 'react';
import { useScrollAnimation } from '../hooks/useScrollAnimation';
import DataLogo from '../assets/DataLogo.jpeg';
import BrightLogo from '../assets/BrightLogo.jpeg';
import HolidayLogo from '../assets/holiday_logo.png';
import './Experience.css';

const jobs = [
  {
    id: 'holidaychannel',
    logo: HolidayLogo,
    company: 'Holiday Channel',
    role: 'Software Engineer Intern',
    period: 'Current',
    location: 'Colorado, USA',
    badge: 'Current',
    bullets: [
      'Developing dynamic frontend components with React and TypeScript, enhancing application responsiveness.',
      'Designing and optimizing backend services using Node.js and MongoDB for efficient data handling.',
      'Implementing JWT and OAuth authentication to strengthen application security.',
      'Optimizing database queries and indexes to reduce query execution time.',
      'Automating deployment pipelines with Docker and CI/CD workflows.',
      'Collaborating cross-functionally to troubleshoot production issues and maintain system stability.',
    ],
  },
  {
    id: 'datalyzer',
    logo: DataLogo,
    company: 'Datalyzer International',
    role: 'Software Engineer',
    period: 'Feb 2021 – Jul 2023',
    location: 'Bengaluru, India',
    badge: '2.5 yrs',
    bullets: [
      'Led design and implementation of scalable RESTful APIs in C#, improving data exchange across the platform.',
      'Optimized relational database schemas for high-transaction environments, boosting performance by 50%.',
      'Built dynamic Angular UI features improving user engagement by 20%.',
      'Implemented lazy loading and architectural optimizations achieving 50% faster page load times.',
      'Provided on-call technical support ensuring 99.9% system uptime; reduced downtime by 30%.',
      'Mentored junior developers on software design best practices and code quality standards.',
    ],
  },
  {
    id: 'brightchamps',
    logo: BrightLogo,
    company: 'BrightChamps',
    role: 'Software Engineer (Freelance)',
    period: 'Mar 2021 – Jul 2023',
    location: 'Bengaluru, India',
    badge: 'Freelance',
    bullets: [
      'Built scalable web and mobile applications using JavaScript, Python, C++, and HTML.',
      'Designed a cloud billing analysis tool on GCP (BigQuery, DataFlow) for real-time leadership insights.',
      'Integrated RESTful APIs between frontend and backend, improving system responsiveness.',
      'Optimized PostgreSQL queries, significantly reducing execution time and improving data retrieval.',
      'Implemented OAuth and JWT authentication for secure application access.',
      'Developed reusable React components and automated CI/CD deployment pipelines.',
    ],
  },
];

const Experience = () => {
  const [open, setOpen] = useState(null);
  const [headerRef, headerIn] = useScrollAnimation();

  return (
    <section id="services" className="exp-section">
      <div className="container">
        <div ref={headerRef} className={`animate ${headerIn ? 'in-view' : ''}`}>
          <span className="section-label">Work History</span>
          <h2 className="section-title">
            Professional <span className="gradient-text">Experience</span>
          </h2>
          <p className="section-sub">
            Three years of hands-on software engineering across product companies and freelance engagements,
            spanning India and the United States.
          </p>
        </div>

        <div className="timeline">
          {jobs.map((job, i) => (
            <TimelineCard
              key={job.id}
              job={job}
              index={i}
              isOpen={open === job.id}
              onToggle={() => setOpen(open === job.id ? null : job.id)}
            />
          ))}
        </div>
      </div>
    </section>
  );
};

function TimelineCard({ job, index, isOpen, onToggle }) {
  const [ref, inView] = useScrollAnimation();

  return (
    <div ref={ref} className={`tl-item animate d${index + 1} ${inView ? 'in-view' : ''}`}>
      <div className="tl-marker">
        <div className="tl-dot" />
      </div>

      <div className={`tl-card glass-card ${isOpen ? 'tl-open' : ''}`}>
        <div className="tl-header" onClick={onToggle} role="button" tabIndex={0}
          onKeyDown={e => e.key === 'Enter' && onToggle()}>
          <div className="tl-logo-wrap">
            <img src={job.logo} alt={job.company} className="tl-logo" />
          </div>
          <div className="tl-info">
            <div className="tl-top">
              <div>
                <h3 className="tl-company">{job.company}</h3>
                <p className="tl-role">{job.role}</p>
              </div>
              <span className="tl-badge">{job.badge}</span>
            </div>
            <div className="tl-meta">
              <span>{job.period}</span>
              <span className="tl-dot-sep">·</span>
              <span>{job.location}</span>
            </div>
          </div>
          <span className={`tl-chevron ${isOpen ? 'up' : ''}`}>
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M6 9l6 6 6-6" />
            </svg>
          </span>
        </div>

        <div className={`tl-body ${isOpen ? 'tl-body-open' : ''}`}>
          <ul className="tl-bullets">
            {job.bullets.map((b, i) => (
              <li key={i} className="tl-bullet">
                <span className="bullet-dot" />
                {b}
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
}

export default Experience;
